// src/data/particle/index.ts
// Particle manifest for the portrait reveal. Generated by
// scripts/particle-sample.py — do not edit by hand.

interface ParticleRecord {
  /** Position as a fraction of image width (0..1). */
  x: number
  /** Position as a fraction of image height (0..1). */
  y: number
  /** Color sampled from the image at this position. */
  r: number
  g: number
  b: number
}

export interface ParticleManifest {
  slug: string
  label: string
  source: string
  sourceSize: [number, number]
  aspect: number
  count: number
  particles: ParticleRecord[]
}

import data from './portrait.json'
export const PORTRAIT_PARTICLES: ParticleManifest = data as ParticleManifest
